---@alias gcp.sqladmin_v1.PscAutoConnectionConfigInstanceAutoDnsStatusEnum "AUTO_DNS_STATUS_UNSPECIFIED"|"AUTO_DNS_OK"|"AUTO_DNS_FAILED"|"AUTO_DNS_UNKNOWN"

